import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int input_height,
    int input_width,
    int kernel_size,
    int stride_h,
    int padding_h,
    int dilation_h,
    int output_height,
    int output_width
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * in_channels * output_height * output_width;
    if (index >= total_elements) return;

    int w = index % output_width;
    index /= output_width;
    int h_out = index % output_height;
    index /= output_height;
    int c = index % in_channels;
    int b = index / in_channels;

    if (b >= batch_size) return;

    float sum = 0.0f;

    for (int k = 0; k < kernel_size; ++k) {
        int h_in = h_out * stride_h - padding_h + k * dilation_h;
        if (h_in >= 0 && h_in < input_height) {
            int input_idx = ((b * in_channels + c) * input_height + h_in) * input_width + w;
            sum += input[input_idx] * weight[c * kernel_size + k];
        }
    }

    if (bias != nullptr) {
        sum += bias[c];
    }

    int output_idx = ((b * in_channels + c) * output_height + h_out) * output_width + w;
    output[output_idx] = sum;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int kernel_size,
    int stride_h,
    int padding_h,
    int dilation_h
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_height = input.size(2);
    int input_width = input.size(3);

    int output_height = (input_height + 2 * padding_h - dilation_h * (kernel_size - 1) - 1) / stride_h + 1;
    int output_width = input_width;

    auto output = torch::zeros({batch_size, in_channels, output_height, output_width}, input.options());

    int total_elements = batch_size * in_channels * output_height * output_width;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    const float* input_ptr = input.contiguous().data_ptr<float>();
    const float* weight_ptr = weight.contiguous().data_ptr<float>();
    const float* bias_ptr = bias ? bias->contiguous().data_ptr<float>() : nullptr;

    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input_ptr,
        weight_ptr,
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        input_height,
        input_width,
        kernel_size,
        stride_h,
        padding_h,
        dilation_h,
        output_height,
        output_width
    );

    return output;
}
"""

depthwise_conv2d_cpp_source = """
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int kernel_size,
    int stride_h,
    int padding_h,
    int dilation_h
);
"""

depthwise_conv2d = load_inline(
    name='depthwise_conv2d',
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=['depthwise_conv2d_cuda'],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        self.weight = nn.Parameter(torch.Tensor(in_channels, 1, kernel_size, 1))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(in_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return depthwise_conv2d.depthwise_conv2d_cuda(
            x.contiguous(),
            self.weight,
            self.bias,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation
        )
